svg.script:
function init(evt) {

  canvas = new Canvas(evt);
}

function Hexagon() {

	this.tileWidth  = 300.0;
	this.tileHeight = 173.2;

	this.centreOffsetX = this.tileWidth / 2;
	this.centreOffsetY = this.tileHeight / 2;

	return this;
}

function click(evt) {

  var hexagon = new Hexagon();
  var xy = canvas.getCoordinates(evt);

  moveElementTo(document.getElementById("circle"), xy);

  var rx = Math.round((xy.x + hexagon.centreOffsetX) / hexagon.tileWidth);
  var ry = Math.round((xy.y + hexagon.centreOffsetY) / hexagon.tileHeight); 
  var red = new Point(rx * hexagon.tileWidth - hexagon.centreOffsetX, ry * hexagon.tileHeight - hexagon.centreOffsetY);

  var bx = Math.round(xy.x / hexagon.tileWidth);
  var by = Math.round(xy.y / hexagon.tileHeight);
  var blue = new Point(bx * hexagon.tileWidth, by * hexagon.tileHeight);

  var dr = Math.sqrt((xy.x - red.x)**2 + (xy.y - red.y)**2);
  var db = Math.sqrt((xy.x - blue.x)**2 + (xy.y - blue.y)**2);

  if ( db < dr) moveElementTo(document.getElementById("hex"), blue);
  else moveElementTo(document.getElementById("hex"), red);
}
